    /**
     * Tests getting all MessagingEndpoints.
     *
     * @return    Collection
     */
    public List<MessagingEndpoint> testGetAll() throws Throwable {
    LOGGER.info( "MessagingEndpointTest:testGetAll() - Retrieving Collection of MessagingEndpoints:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all MessagingEndpoint : " );
    List<MessagingEndpoint> collection  = null;

    try {
        // call the static get method on the MessagingEndpointService
        collection = service.getAllMessagingEndpoint();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            MessagingEndpoint currEntity  = null;
            Iterator<MessagingEndpoint> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getMessagingEndpointId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

